import java.util.*;

class Solution {
  public int[] rearrangeArray(int[] nums) {
    Arrays.sort(nums);
    int[] result = new int[nums.length];
    int p = 0;
    for (int i = 0; i < nums.length; i += 2) result[i] = nums[p++];
    for (int i = 1; i < nums.length; i += 2) result[i] = nums[p++];
    return result;
  }
}
